.dashboardSidebar-container {
  position: sticky;
  top: 0;
  width: 270px;
  height: 100vh;
  overflow: hidden;
  border: 1px solid var(--border);
}

.dashboard-logo {
  padding: 8px 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
}
.dashboard-logo>img {
  width: 60px;
}

/* dashboard list */
.dashboardSidebar-list {
  padding: 7px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-bottom: 1px solid var(--border);
}

.dashboard-navlink {
  color: var(--text_secondary);
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 12px 20px;
  border-radius: 10px;
  border: 1px solid transparent;
  transition: var(--transition);
}

.dashboard-navlink:hover {
  background-color: var(--surface_hover);
  color: var(--text_primary);
}

.dashboard-navlink.active {
  background-color: rgba(41, 163, 224, 0.12);
  border-color: var(--primary);
  color: var(--primary);
  font-weight: 600;
}

.dashboard-navlink.active svg {
  color: var(--primary) !important;
}
.dashboard-navlink>span {
  font-size: 14px;
}

/* dashboard logout */
.dashboard-logout {
  padding: 5px;
}
.dashboard-logout>div {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 20px;
  border-radius: 10px;
}
.dashboard-logout>div:hover {
  background-color: var(--surface_hover);
}
.collapse>span {
  font-size: 13px;
  cursor: pointer;
}
.logout-div>span {
  font-size: 15px;
  color: red;
  cursor: pointer;
}

/* ================= COLLAPSED ================= */
.dashboardSidebar-container.collapsed {
  width: 75px;
}

.admin-logout-overlay {
  position: fixed;
  inset: 0;
  z-index: 100000;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(8, 13, 24, .66);
  backdrop-filter: blur(5px);
}

.admin-logout-modal {
  width: min(420px, 100%);
  padding: 30px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: var(--surface);
  color: var(--text_primary);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .28);
  text-align: center;
  animation: admin-logout-enter .2s ease-out;
}

.admin-logout-icon {
  display: grid;
  width: 54px;
  height: 54px;
  margin: 0 auto 17px;
  place-items: center;
  border-radius: 16px;
  background: color-mix(in srgb, #e0525d 13%, transparent);
  color: #e0525d;
  font-size: 24px;
}

.admin-logout-modal h2 {
  margin: 0;
  font-size: 19px;
}

.admin-logout-modal>p {
  margin: 10px 0 0;
  color: var(--text_secondary);
  font-size: 13px;
  line-height: 1.55;
}

.admin-logout-error {
  margin-top: 15px;
  color: #e0525d;
  font-size: 12px;
}

.admin-logout-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 25px;
}

.admin-logout-actions button {
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid var(--border);
  border-radius: 10px;
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  cursor: pointer;
}

.admin-logout-actions button:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.admin-logout-cancel {
  background: var(--surface_secondary, var(--surface));
  color: var(--text_primary);
}

.admin-logout-confirm {
  border-color: #d64c57 !important;
  background: #d64c57;
  color: #fff;
}

.admin-logout-actions .admin-logout-cancel:hover:not(:disabled) {
  background: var(--button);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--button) 17%, transparent);
}

.admin-logout-actions .admin-logout-confirm:hover:not(:disabled) {
  border-color: var(--primary) !important;
  background: transparent;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 17%, transparent);
}

@keyframes admin-logout-enter {
  from {
    opacity: 0;
    transform: translateY(9px) scale(.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 430px) {
  .admin-logout-modal {
    padding: 25px 20px;
  }

  .admin-logout-actions {
    flex-direction: column-reverse;
  }

  .admin-logout-actions button {
    width: 100%;
  }
}
.dashboardSidebar-container.collapsed .dashboard-navlink span,
.dashboardSidebar-container.collapsed .collapse span,
.dashboardSidebar-container.collapsed .logout-div span {
  display: none;
}

.dashboardSidebar-container.collapsed .dashboard-navlink {
  justify-content: center;
  padding: 12px 0;
}

.dashboardSidebar-container.collapsed .collapse,
.dashboardSidebar-container.collapsed .logout-div {
  justify-content: center;
  cursor: pointer;
}

.collapse svg {
  transition: transform 0.3s ease;
}

.dashboardSidebar-container.collapsed .collapse svg {
  transform: rotate(180deg);
}

.dashboardSidebar-container {
  width: var(--sidebar_width);
  height: 100vh;
  overflow: hidden;
  transition: width 0.4s ease-in-out;
}

.dashboardSidebar-container.collapsed {
  width: 75px;
}

@media (max-width: 840px) {
  .dashboardSidebar-container {
    position: relative;
    width: 100%;
    height: auto;
    overflow: visible;
    background: var(--bg);
  }

  .dashboard-logo {
    padding: 12px 18px;
  }

  .dashboardSidebar-list {
    flex-direction: row;
    overflow-x: auto;
    border-top: 1px solid var(--border);
    scrollbar-width: thin;
  }

  .dashboard-navlink {
    flex: 0 0 auto;
    gap: 8px;
    padding: 10px 12px;
  }

  .dashboard-logout {
    display: flex;
    gap: 8px;
    padding: 8px 12px;
  }

